(function(){const list=document.getElementById("report-metric-order"),safety=document.getElementById("safety-metric-order");if(!list)return;document.querySelectorAll(".metric-focus-editor").forEach(editor=>{const row=Array.from([...list.children,...(safety?Array.from(safety.children):[])]).find(li=>li.dataset.metric===editor.dataset.forMetric);if(row)row.appendChild(editor);});})();
